      "上下文窗口:模型一次能处理的最大 token 数(GPT-4 128K/Claude 200K)——窗口内所有内容(系统提示+检索片段+对话历史+用户问题)共享窗口;超出→截断或压缩(第 32 题压缩方案)。",
